const cache = new Map<number, QcfPage>();

export function getQcfPage(page: number): QcfPage | null {
  if (page < 1 || page > 604) return null;
  const cached = cache.get(page);
  if (cached) return cached;
  const thunk = PAGE_THUNKS[page];
  if (!thunk) return null;
  const data = thunk();
  cache.set(page, data);
  return data;
}
